//! Designed valve leaflets (brief B36): the mitral leaflets and the aortic and pulmonary cusps,
//! generated by rule from published dimensions on this heart's own valve discs, as an
//! [`AnimatedValve`] (the `HSAV` record of the measured tricuspid valve, brief B35), so a measured
//! valve can later replace a designed one by replacing one file.
//!
//! **What these are.** Designed shapes, not the anatomy of a person and not reviewed by a
//! clinician. Every number is in [`MitralDesign`] or [`CuspDesign`] with its source, or marked
//! **Designed** with the reason (`docs/research/designed-valve-leaflets.md`). No lesion is implied.
//!
//! **Pure.** [`mitral`] and [`semilunar`] are functions of the disc rim, the orientation
//! directions the caller derives from the heart's landmarks, the parameters and (optionally) the
//! blood label volume the leaflets must stay in. No I/O, no randomness, no solver iterations
//! whose count depends on anything but those inputs; the same input gives the same bytes.
//!
//! **Shapes.** Each leaflet is a strip of *columns* hung from the rim (row 0, the annulus) to the
//! free edge (the last row), triangulated column by column. [`SHAPES`] keyframes run from open
//! (the rest shape) to shut, evenly in the generator's motion parameter, so no vertex moves more
//! than a fraction of its path between two keyframes:
//! * *atrioventricular* (mitral): each column keeps its length and swings in its own plane about
//!   the hinge, its tangent angle blended from the straight open column to the shut column (an arc
//!   with a slight billow, then the coaptation zone hanging downstream). The anterior and the
//!   posterior column of one place along the coaptation line meet at one point, solved as the
//!   designed cone of the echo does for the whole valve, so the shut valve is competent;
//! * *semilunar* (aortic, pulmonary): three cusps attached along a crown from commissure to
//!   commissure; shut, the free edges run straight from the commissures to the centre at the
//!   effective height with the coaptation zone below; open, the free edges lie toward the wall
//!   and leave a rounded-triangle orifice. Each cusp stays in its own 120° wedge about the axis at
//!   every opening, so the cusps never cross.
//!
//! **Layout.** Leaflet vertex `column × (rows + 1) + row` (row 0 on the annulus, the last row on
//! the free edge); the mitral columns run once around the rim from the posteromedial commissure
//! through the anterior leaflet, the cusp columns cusp by cusp from one commissure to the next.
//! The chordae-only vertices follow the leaflet vertices.

#![allow(
    clippy::manual_midpoint,
    clippy::manual_clamp,
    clippy::cast_possible_wrap,
    clippy::items_after_statements,
    reason = "the arithmetic is written as baked: `f32::midpoint` and `clamp` round or panic differently, \
              and the committed pack files are its bytes; column indices are a few hundred"
)]

use crate::valve::{AnimatedValve, DiscRim, RIM_BINS, ValveKeyframe};
use crate::volume::{Label, LabelVolume};
use glam::{Vec2, Vec3};
use std::f32::consts::{FRAC_PI_2, PI};

/// Shapes per designed valve, the open rest shape included (the brief allows at most eight).
/// **Designed**: seven steps of equal summed path keep every vertex's move per step near a
/// seventh of its path.
pub const SHAPES: usize = 8;
/// A leaflet vertex the containment fit leaves at most this far outside its valve's blood, mm
/// (the acceptance test allows 1 mm). **Designed**, as `CONTAIN_TARGET_MM` of the B35 bake.
pub const CONTAIN_TARGET_MM: f32 = 0.6;

/// Why a designed valve could not be built.
#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
pub enum DesignError {
    #[error("designed valve: {0}")]
    Geometry(String),
}

/// Parameters of the designed mitral valve (`docs/research/designed-valve-leaflets.md`, table
/// "Mitral valve" and the last section). Lengths in mm, angles in degrees.
#[derive(Debug, Clone, PartialEq)]
pub struct MitralDesign {
    /// Anterior leaflet length, annulus to free edge at mid-leaflet (M1): **25.1 mm**, Tarkiainen
    /// 2016 Table 1 via `DesignedParams::mitral_anterior_length_mm`.
    pub anterior_length_mm: f32,
    /// Posterior leaflet length at the middle of its middle scallop P2 (M2, R2): **14.4 mm**, same
    /// table (Ranganathan 1970 Table 2 gives 14 / 12 mm for the middle scallop).
    pub posterior_length_mm: f32,
    /// Heights of the scallops P1, P2, P3 at their middles against P2 (R6): **0.81 : 1 : 0.69**,
    /// derived from Ranganathan 1970 Table 2 (autopsy, 50 valves: the posteromedial scallop is the
    /// shortest).
    pub scallop_heights: [f32; 3],
    /// Share of the annulus taken by the anterior leaflet (M3): **150°**, Kaiser 2019 A.2.2 p. 32
    /// (a design value of that model). The commissures sit at the two ends of this arc (M5).
    pub anterior_arc_deg: f32,
    /// Widths of the posterior scallops P1 : P2 : P3 as fractions of the posterior arc (R5):
    /// **0.31 : 0.42 : 0.27**, derived from the scallop base widths of Ranganathan 1970 Table 2.
    pub scallop_fractions: [f32; 3],
    /// Height lost at a boundary between two scallops, fraction of the lower neighbour's height
    /// (M9): **0.20**, **Designed** (an indentation, under the 0.50 that would make a cleft).
    pub indentation: f32,
    /// Leaflet height at the commissures (R8): **7.5 mm**, the commissural areas' central heights of
    /// Ranganathan 1970 Table 1 (8 / 7 mm anterolateral, 8 / 8 mm posteromedial).
    pub commissure_height_mm: f32,
    /// Overlap of the shut leaflets beyond their meeting line (M13, R11): **8.0 mm**,
    /// `DesignedParams::mitral_coaptation_mm` (Ranganathan 1970 p. 461: the line of closure 8 to
    /// 10 mm from the anterior free margin; maintainer's decision on C1). Where the two columns of a
    /// place are too short for it, less is used (never under [`Self::min_coaptation_mm`]).
    pub coaptation_mm: f32,
    /// Smallest overlap the generator accepts before it reports a gap, mm. **Designed**.
    pub min_coaptation_mm: f32,
    /// Distance between the midsurfaces of two apposed leaflets in the coaptation zone, mm:
    /// **0.8**, **Designed** (half the drawn thickness, so the drawn leaflets touch and the free
    /// edges are under 1 mm apart).
    pub apposition_mm: f32,
    /// Largest billow of a shut leaflet toward the atrium, measured from the straight line hinge
    /// → meeting point, mm: **1.0**, **Designed** under the 1 mm that separates normal from
    /// degenerate billowing (M15, Garbi 2015, secondary); never above the annulus plane.
    pub billow_mm: f32,
    /// Angle of the open leaflet to the valve axis, leaning toward it (M18): **10°**,
    /// `DesignedParams::open_angle_from_axis_deg` (**Designed**).
    pub open_angle_deg: f32,
    /// Chordae per papillary muscle (M19, R12; counts **Designed**, inside Kaiser 2019 A.2.3's
    /// porcine counts), each muscle on its own half of each leaflet (M22): two to the anterior
    /// leaflet at these angles from its centre, degrees (one on the free edge, one in the rough
    /// zone); one commissural chord to its commissure; one cleft chord to the boundary between the
    /// middle scallop and the scallop on its side (Ranganathan 1970: two cleft chordae in every
    /// tri-scalloped leaflet, one fan-shaped commissural chorda per commissure); two to the middle
    /// scallop at these angles from the posterior leaflet's centre toward its side.
    pub chordae_anterior_deg: [f32; 2],
    pub chordae_middle_scallop_deg: [f32; 2],
    /// The rough zone, where chordae insert, as the distal share of the height (R10, Ranganathan
    /// 1970 Table 3): anterior leaflet **0.37**, posterior scallops **0.55**.
    pub rough_zone: [f32; 2],
    /// Radius around the muscle tip the chordae leave from, mm. **Designed** (about the tip radius of
    /// the echo's designed muscle: 8 mm base × 0.6 / 2).
    pub chord_fan_mm: f32,
    /// Drawn chord radius, mm. **Designed** (no chordal diameter was read).
    pub chord_radius_mm: f32,
    /// Columns around the annulus and rows from annulus to free edge (about 2,900 triangles).
    pub columns: usize,
    pub rows: usize,
}

impl Default for MitralDesign {
    fn default() -> Self {
        Self {
            anterior_length_mm: 25.1,
            posterior_length_mm: 14.4,
            anterior_arc_deg: 150.0,
            scallop_heights: [0.81, 1.0, 0.69],
            scallop_fractions: [0.31, 0.42, 0.27],
            indentation: 0.20,
            commissure_height_mm: 7.5,
            coaptation_mm: 8.0,
            min_coaptation_mm: 0.5,
            apposition_mm: 0.8,
            billow_mm: 1.0,
            open_angle_deg: 10.0,
            chordae_anterior_deg: [20.0, 45.0],
            chordae_middle_scallop_deg: [15.0, 30.0],
            rough_zone: [0.37, 0.55],
            chord_fan_mm: 2.4,
            chord_radius_mm: 0.4,
            columns: 144,
            rows: 10,
        }
    }
}

/// Parameters of a designed semilunar valve (`docs/research/designed-valve-leaflets.md`, tables
/// "Aortic valve" and "Pulmonary valve").
#[derive(Debug, Clone, PartialEq)]
pub struct CuspDesign {
    /// Height of the shut cusps' central meeting point above the disc plane (A3/P2): **8.6 mm**,
    /// `DesignedParams::aortic_effective_height_mm` (Izawa 2021) and its pulmonary copy.
    pub effective_height_mm: f32,
    /// When set, the geometric height (nadir to the free-edge midpoint) as a share of the disc's
    /// diameter, and the effective height follows from it by A4 (`√(gH² − R²)`) instead of
    /// [`Self::effective_height_mm`]. The pulmonary valve: **0.66** = 15.5 mm on a 23.4 mm ring,
    /// Lis 2023 Table 1 and section 3.1 (autopsy, 182 hearts; rows L1, L2). `None` for the aortic.
    pub geometric_height_ratio: Option<f32>,
    /// Commissure height over the geometric height `√(R² + eH²)` (A4, A7): **1.25** = 18.6 / 14.9
    /// (Ishida 2026 Table 2, CT); the pulmonary valve takes the aortic ratio (**Designed**, P4).
    pub commissure_ratio: f32,
    /// Height of the apposed zone below the free edge at the centre (A10): **3.3 mm** (De Kerchove
    /// 2018, abstract), tapering to nothing in the last [`Self::zone_taper_deg`] before each
    /// commissure (**Designed**).
    pub coaptation_mm: f32,
    pub zone_taper_deg: f32,
    /// Height of the apposed zone about midway between the centre and a commissure (K5): **5.9 mm**
    /// (De Kerchove 2018, lateral coaptation length); the zone runs from [`Self::coaptation_mm`]
    /// at the centre up to this at 30° and back down (`sin(π |φ| / 60°)`), then tapers to nothing
    /// before the commissure.
    pub lateral_coaptation_mm: f32,
    /// Open orifice area over the disc area (A14): **0.75**, **Designed** (no source read).
    pub open_orifice_fraction: f32,
    /// Distance between the midsurfaces of two apposed cusps, mm: **0.8**, **Designed** (as the
    /// mitral value).
    pub apposition_mm: f32,
    /// Columns per cusp (commissure to commissure; odd, so one column is the cusp's centre) and rows
    /// (attachment to free edge): 31 × 8, about 1,400 triangles for the valve. **Designed**: the
    /// echo's slice through the pulmonary valve is the cost gate (brief B36 item 5), and a denser
    /// cusp mesh made it more than 10 % slower than the designed cone.
    pub columns: usize,
    pub rows: usize,
    /// The columns stop this far short of each commissure, degrees, so no column is degenerate.
    /// **Designed**.
    pub commissure_gap_deg: f32,
}

impl Default for CuspDesign {
    fn default() -> Self {
        Self {
            effective_height_mm: 8.6,
            geometric_height_ratio: None,
            commissure_ratio: 1.25,
            coaptation_mm: 3.3,
            zone_taper_deg: 15.0,
            lateral_coaptation_mm: 5.9,
            open_orifice_fraction: 0.75,
            apposition_mm: 0.8,
            columns: 31,
            rows: 8,
            commissure_gap_deg: 1.5,
        }
    }
}

/// The blood a valve's leaflets must stay in: a label volume and the labels that count.
#[derive(Debug, Clone, Copy)]
pub struct BloodMask<'a> {
    pub volume: &'a LabelVolume,
    pub labels: &'a [Label],
}

impl BloodMask<'_> {
    fn counts(&self, l: u8) -> bool {
        self.labels.iter().any(|x| *x as u8 == l)
    }

    /// Distance from `p` to the nearest voxel box of this blood, searching up to `reach_mm`; `0`
    /// inside, `reach_mm` when none is within reach.
    #[must_use]
    pub fn distance_outside(&self, p: Vec3, reach_mm: f32) -> f32 {
        distance_to_label(self.volume, p, reach_mm, &|l| self.counts(l)).map_or(reach_mm, |x| x.0)
    }
}

/// Distance from `p` to the nearest voxel (as a box) whose label passes `want`, searching up to
/// `reach_mm`; `0` inside such a voxel, `None` when none is within reach. Also the nearest point
/// of that voxel. The B35 tricuspid bake uses the same function.
pub fn distance_to_label(
    vol: &LabelVolume,
    p: Vec3,
    reach_mm: f32,
    want: &dyn Fn(u8) -> bool,
) -> Option<(f32, Vec3)> {
    if let Some(l) = vol.get(p)
        && want(l)
    {
        return Some((0.0, p));
    }
    let s = vol.spacing_mm;
    let r = (reach_mm / s).ceil() as i64;
    let rel = (p - vol.origin_mm) / s;
    let (ci, cj, ck) = (rel.x.floor() as i64, rel.y.floor() as i64, rel.z.floor() as i64);
    let [nx, ny, nz] = vol.dims.map(i64::from);
    let mut best: Option<(f32, Vec3)> = None;
    for k in (ck - r).max(0)..=(ck + r).min(nz - 1) {
        for j in (cj - r).max(0)..=(cj + r).min(ny - 1) {
            for i in (ci - r).max(0)..=(ci + r).min(nx - 1) {
                let l = vol.labels[vol.index(i as u32, j as u32, k as u32)];
                if !want(l) {
                    continue;
                }
                let lo = vol.origin_mm + Vec3::new(i as f32, j as f32, k as f32) * s;
                let q = p.clamp(lo, lo + Vec3::splat(s));
                let d = q.distance(p);
                if best.is_none_or(|(bd, _)| d < bd) {
                    best = Some((d, q));
                }
            }
        }
    }
    best.filter(|(d, _)| *d <= reach_mm)
}

/// A valve disc as the generator sees it: the rim curve ([`DiscRim::rim_points`] of the rest
/// disc), its centre and its downstream normal.
#[derive(Debug, Clone)]
pub struct DiscFrame {
    pub rim: DiscRim,
    pub rim_mm: Vec<Vec3>,
}

impl DiscFrame {
    /// The frame of the disc whose rest vertices are `points`, its normal toward `downstream_mm`.
    #[must_use]
    pub fn new(points: &[Vec3], downstream_mm: Vec3) -> Option<Self> {
        let rim = DiscRim::new(points, downstream_mm)?;
        let rim_mm = rim.rim_points(points);
        Some(Self { rim, rim_mm })
    }

    /// The disc centre (mean of the disc vertices), mm.
    #[must_use]
    pub fn centre(&self) -> Vec3 {
        self.rim.centre_mm
    }

    /// The downstream unit normal.
    #[must_use]
    pub fn normal(&self) -> Vec3 {
        self.rim.normal
    }

    /// `d` projected on the disc plane and normalised (`None` when it is along the normal).
    #[must_use]
    pub fn in_plane(&self, d: Vec3) -> Option<Vec3> {
        let n = self.normal();
        let p = d - n * d.dot(n);
        (p.length() > 1e-6).then(|| p.normalize())
    }

    /// The rim point at the azimuth of the in-plane unit direction `dir` from the centre.
    #[must_use]
    pub fn rim_at_dir(&self, dir: Vec3) -> Vec3 {
        let phi = self.rim.param(&self.rim_mm, self.centre() + dir * 10.0);
        DiscRim::rim_at(&self.rim_mm, phi)
    }

    /// Mean in-plane distance of the rim from the centre, mm.
    #[must_use]
    pub fn mean_radius_mm(&self) -> f32 {
        let n = self.normal();
        self.rim_mm
            .iter()
            .map(|p| {
                let d = *p - self.centre();
                (d - n * d.dot(n)).length()
            })
            .sum::<f32>()
            / RIM_BINS as f32
    }

    /// Area enclosed by the rim projected on the disc plane, mm².
    #[must_use]
    pub fn area_mm2(&self) -> f32 {
        polygon_area(&self.rim_mm.iter().map(|p| self.to2(*p)).collect::<Vec<_>>())
    }

    /// In-plane coordinates of `p` about the centre (along the rim's `u`, `v`).
    #[must_use]
    pub fn to2(&self, p: Vec3) -> Vec2 {
        let d = p - self.centre();
        Vec2::new(d.dot(self.rim.u), d.dot(self.rim.v))
    }
}

/// Area of a closed polygon (absolute shoelace), mm².
#[must_use]
pub fn polygon_area(pts: &[Vec2]) -> f32 {
    let n = pts.len();
    if n < 3 {
        return 0.0;
    }
    (0..n)
        .map(|i| pts[i].perp_dot(pts[(i + 1) % n]))
        .sum::<f32>()
        .abs()
        * 0.5
}

/// A designed valve and the numbers the brief asks to report.
#[derive(Debug, Clone)]
pub struct DesignedValve {
    pub valve: AnimatedValve,
    /// One line per finding (lengths, areas, coaptation, containment, opening fit).
    pub report: Vec<String>,
    /// Worst distance of a leaflet vertex outside the valve's blood over every keyframe, mm, with
    /// the shape and vertex (0 without a blood mask).
    pub worst_outside: (f32, usize, usize),
    /// The opening the containment fit kept (1 = the designed opening), smallest and mean over the
    /// columns.
    pub opening_kept: (f32, f32),
}

// --- shared machinery ---------------------------------------------------------------------------

fn smoothstep(t: f32) -> f32 {
    let t = t.clamp(0.0, 1.0);
    t * t * (3.0 - 2.0 * t)
}

/// One column's motion: its row positions at motion parameter `c` (0 open … 1 shut).
trait Column {
    fn at(&self, c: f32, out: &mut Vec<Vec3>);
}

/// A mitral column: hinge `h`, its plane (`e` toward the meeting point, `n` downstream, `b`
/// sideways), length `len`, the open tangent angle, and the shut tangent angle profile (linear over
/// the arc `0..arc`, `π/2` over the coaptation zone `arc..len`), plus a sideways drift `w` reached
/// at the end of the arc (zero unless the plane had to be chosen off the meeting point).
#[derive(Debug, Clone)]
struct AvColumn {
    h: Vec3,
    e: Vec3,
    n: Vec3,
    b: Vec3,
    len: f32,
    arc: f32,
    theta_open: f32,
    theta_start: f32,
    theta_end: f32,
    w: f32,
    rows: usize,
}

impl AvColumn {
    /// The point at arc length `s` for blend `c`: the tangent angle is
    /// `θo + c·(θs(s) − θo)`, linear in `s` on each part, integrated exactly.
    fn point(&self, c: f32, s: f32) -> Vec3 {
        let lin = |a0: f32, a1: f32, l: f32| -> Vec2 {
            // ∫0^l (cos, sin)(a0 + (a1 − a0) t / l) dt
            if l <= 0.0 {
                return Vec2::ZERO;
            }
            let k = (a1 - a0) / l;
            if k.abs() < 1e-6 {
                let m = 0.5 * (a0 + a1);
                Vec2::new(m.cos(), m.sin()) * l
            } else {
                Vec2::new((a1.sin() - a0.sin()) / k, (a0.cos() - a1.cos()) / k)
            }
        };
        let to = self.theta_open;
        let blend = |t: f32| to + c * (t - to);
        let s1 = s.min(self.arc);
        let a0 = blend(self.theta_start);
        let a_s1 = blend(self.theta_start + (self.theta_end - self.theta_start) * (s1 / self.arc.max(1e-6)));
        let mut p = lin(a0, a_s1, s1);
        if s > self.arc {
            let z = blend(FRAC_PI_2);
            p += Vec2::new(z.cos(), z.sin()) * (s - self.arc);
        }
        let w = self.w * c * (s / self.arc.max(1e-6)).min(1.0);
        self.h + self.e * p.x + self.n * p.y + self.b * w
    }
}

impl AvColumn {
    /// Arc length of row `r`: rows evenly over the arc and over the coaptation zone, in shares
    /// of the length (one row falls on the corner between them, so the drawn column keeps its
    /// length).
    fn row_s(&self, r: usize) -> f32 {
        let zone = (self.len - self.arc).max(0.0);
        let n_zone = if zone > 1e-3 {
            ((self.rows as f32 * zone / self.len).round() as usize).clamp(1, self.rows - 1)
        } else {
            0
        };
        let n_arc = self.rows - n_zone;
        if r <= n_arc {
            self.arc.min(self.len) * r as f32 / n_arc as f32
        } else {
            self.arc + zone * (r - n_arc) as f32 / n_zone as f32
        }
    }
}

impl Column for AvColumn {
    fn at(&self, c: f32, out: &mut Vec<Vec3>) {
        out.clear();
        for r in 0..=self.rows {
            out.push(self.point(c, self.row_s(r)));
        }
    }
}

/// A cusp column: rows evenly along the shut polyline `shut` and the open polyline `open` (same
/// arc-length fractions), blended linearly (each cusp stays in its convex wedge).
#[derive(Debug, Clone)]
struct LerpColumn {
    shut: Vec<Vec3>,
    open: Vec<Vec3>,
}

impl Column for LerpColumn {
    fn at(&self, c: f32, out: &mut Vec<Vec3>) {
        out.clear();
        out.extend(self.open.iter().zip(&self.shut).map(|(o, s)| o.lerp(*s, c)));
    }
}

/// `rows + 1` points evenly by arc length along the polyline `pts`.
fn resample(pts: &[Vec3], rows: usize) -> Vec<Vec3> {
    let seg: Vec<f32> = pts.windows(2).map(|w| w[0].distance(w[1])).collect();
    let total: f32 = seg.iter().sum();
    (0..=rows)
        .map(|r| {
            let mut s = total * r as f32 / rows as f32;
            for (i, l) in seg.iter().enumerate() {
                if s <= *l || i == seg.len() - 1 {
                    return pts[i].lerp(pts[i + 1], (s / l.max(1e-9)).clamp(0.0, 1.0));
                }
                s -= l;
            }
            pts[pts.len() - 1]
        })
        .collect()
}

/// The strips of columns: per leaflet strip, its columns in order and the leaflet id of each
/// quad between two neighbouring columns (`closed` strips wrap around).
struct Strips {
    /// Per strip: (first column index, column count, closed).
    strips: Vec<(usize, usize, bool)>,
    /// Leaflet id of the quad between column `i` and the next one in its strip.
    quad_leaflet: Vec<u8>,
}

/// Everything after the columns: the per-column opening fit against the blood, the keyframes, the
/// chordae, and the record. `extra` are chordae-only vertices (fixed at their rest positions) and
/// `chords` their segments, as (chordae vertex index into `extra`, column, row).
#[allow(clippy::too_many_arguments)]
fn assemble(
    name: &str,
    leaflet_names: &[&str],
    columns: &[Box<dyn Column>],
    rows: usize,
    strips: &Strips,
    extra: &[Vec3],
    chords: &[(usize, usize, usize)],
    chord_radius_mm: f32,
    blood: Option<&BloodMask<'_>>,
    report: &mut Vec<String>,
) -> Result<DesignedValve, DesignError> {
    let nc = columns.len();
    let per = rows + 1;
    let nl = nc * per;
    // the opening each column keeps: the largest of 1, 0.95, … whose open shape stays within the
    // target of the blood; then eroded and blurred along the strips so it varies smoothly (both
    // steps can only lower it)
    let mut keep = vec![1.0f32; nc];
    let mut buf = Vec::new();
    if let Some(mask) = blood {
        for (i, col) in columns.iter().enumerate() {
            let mut k = 20;
            while k > 0 {
                let lambda = k as f32 / 20.0;
                col.at(1.0 - lambda, &mut buf);
                if buf
                    .iter()
                    .all(|p| mask.distance_outside(*p, 4.0) <= CONTAIN_TARGET_MM)
                {
                    break;
                }
                k -= 1;
            }
            keep[i] = k as f32 / 20.0;
        }
        for &(first, count, closed) in &strips.strips {
            let idx = |j: isize| -> Option<usize> {
                if closed {
                    Some(first + j.rem_euclid(count as isize) as usize)
                } else if (0..count as isize).contains(&j) {
                    Some(first + j as usize)
                } else {
                    None
                }
            };
            let src = keep.clone();
            let eroded: Vec<f32> = (0..count as isize)
                .map(|j| {
                    (-3..=3)
                        .filter_map(|o| idx(j + o))
                        .map(|q| src[q])
                        .fold(1.0f32, f32::min)
                })
                .collect();
            for j in 0..count as isize {
                let vals: Vec<f32> = (-3..=3)
                    .filter_map(|o| idx(j + o).map(|q| eroded[q - first]))
                    .collect();
                keep[first + j as usize] = vals.iter().sum::<f32>() / vals.len() as f32;
            }
        }
    }
    let kept_min = keep.iter().copied().fold(1.0f32, f32::min);
    let kept_mean = keep.iter().sum::<f32>() / nc as f32;
    // the shapes: column i from c = 1 − keep_i (its open shape) to c = 1 (shut), the keyframes
    // where its vertices have covered equal shares of their summed path (so no keyframe step
    // takes much more than a sixth of any vertex's path)
    let mut col_c: Vec<[f32; SHAPES]> = Vec::with_capacity(nc);
    let (mut prev, mut cur) = (Vec::new(), Vec::new());
    for (i, col) in columns.iter().enumerate() {
        const FINE: usize = 120;
        let c0 = 1.0 - keep[i];
        let at = |j: usize| c0 + (1.0 - c0) * j as f32 / FINE as f32;
        let mut cum = vec![0.0f32; FINE + 1];
        col.at(at(0), &mut prev);
        for j in 1..=FINE {
            col.at(at(j), &mut cur);
            cum[j] = cum[j - 1] + prev.iter().zip(&cur).map(|(a, b)| a.distance(*b)).sum::<f32>();
            std::mem::swap(&mut prev, &mut cur);
        }
        let total = cum[FINE];
        let mut cs = [1.0f32; SHAPES];
        for (k, ck) in cs.iter_mut().enumerate() {
            if k + 1 == SHAPES {
                break;
            }
            if total <= 1e-6 {
                *ck = c0 + (1.0 - c0) * k as f32 / (SHAPES - 1) as f32;
                continue;
            }
            let want = total * k as f32 / (SHAPES - 1) as f32;
            let j = cum.partition_point(|x| *x < want).clamp(1, FINE);
            let f = ((want - cum[j - 1]) / (cum[j] - cum[j - 1]).max(1e-9)).clamp(0.0, 1.0);
            *ck = if k == 0 {
                c0
            } else {
                at(j - 1) + (at(j) - at(j - 1)) * f
            };
        }
        col_c.push(cs);
    }
    let shapes: Vec<Vec<Vec3>> = (0..SHAPES)
        .map(|k| {
            let mut s = Vec::with_capacity(nl + extra.len());
            for (i, col) in columns.iter().enumerate() {
                col.at(col_c[i][k].clamp(0.0, 1.0), &mut buf);
                s.extend_from_slice(&buf);
            }
            s.extend_from_slice(extra);
            s
        })
        .collect();
    let nv = nl + extra.len();
    // topology
    let vid = |col: usize, row: usize| (col * per + row) as u32;
    let mut triangles = Vec::new();
    let mut triangle_leaflet = Vec::new();
    for &(first, count, closed) in &strips.strips {
        let quads = if closed { count } else { count - 1 };
        for j in 0..quads {
            let (a, b) = (first + j, first + (j + 1) % count);
            let l = strips.quad_leaflet[a];
            for r in 0..rows {
                let (p, q, s, t) = (vid(a, r), vid(b, r), vid(b, r + 1), vid(a, r + 1));
                triangles.push([p, q, s]);
                triangles.push([p, s, t]);
                triangle_leaflet.extend([l, l]);
            }
        }
    }
    let mut vertex_leaflet = vec![u8::MAX; nv];
    for (t, l) in triangles.iter().zip(&triangle_leaflet) {
        for &i in t {
            if vertex_leaflet[i as usize] == u8::MAX {
                vertex_leaflet[i as usize] = *l;
            }
        }
    }
    let chordae: Vec<[u32; 2]> = chords
        .iter()
        .map(|&(x, col, row)| [(nl + x) as u32, vid(col, row)])
        .collect();
    for (s, c) in chordae.iter().zip(chords) {
        vertex_leaflet[s[0] as usize] = vertex_leaflet[vid(c.1, c.2) as usize];
    }
    for l in &mut vertex_leaflet {
        if *l == u8::MAX {
            *l = 0;
        }
    }
    let annulus: Vec<u32> = (0..nc).map(|c| vid(c, 0)).collect();
    let free_edge: Vec<u32> = (0..nc).map(|c| vid(c, rows)).collect();
    let mut follow_weight = vec![0.0f32; nv];
    for c in 0..nc {
        for r in 0..=rows {
            follow_weight[vid(c, r) as usize] = 1.0 - smoothstep(r as f32 / rows as f32);
        }
    }
    // quantise the offsets from the rest (open) shape
    let rest = shapes[0].clone();
    let max_off = shapes
        .iter()
        .flat_map(|s| s.iter().zip(&rest).map(|(p, r)| (*p - *r).abs().max_element()))
        .fold(0.0f32, f32::max);
    let quantum_mm = (1.0f32 / 1024.0).max(max_off / 32_000.0);
    let offsets: Vec<Vec<[i16; 3]>> = shapes[1..]
        .iter()
        .map(|s| {
            s.iter()
                .zip(&rest)
                .map(|(p, r)| ((*p - *r) / quantum_mm).round().to_array().map(|x| x as i16))
                .collect()
        })
        .collect();
    let deq = |off: &[[i16; 3]]| -> Vec<Vec3> {
        rest.iter()
            .zip(off)
            .map(|(r, o)| *r + Vec3::new(f32::from(o[0]), f32::from(o[1]), f32::from(o[2])) * quantum_mm)
            .collect()
    };
    let shut = deq(&offsets[offsets.len() - 1]);
    let coaptation_mm = free_edge.iter().map(|&i| shut[i as usize]).sum::<Vec3>() / free_edge.len() as f32;
    let metric = |pos: &[Vec3]| {
        free_edge
            .iter()
            .map(|&i| pos[i as usize].distance(coaptation_mm))
            .sum::<f32>()
            / free_edge.len() as f32
    };
    let m: Vec<f32> = std::iter::once(metric(&rest))
        .chain(offsets.iter().map(|o| metric(&deq(o))))
        .collect();
    let (m0, m1) = (m[0], m[m.len() - 1]);
    if m0 <= m1 + 0.5 {
        return Err(DesignError::Geometry(format!(
            "{name}: the shut free edge is not nearer the coaptation point ({m0:.2} vs {m1:.2} mm; opening \
             kept per column min {kept_min:.2} / mean {kept_mean:.2}); {}",
            report.join("; ")
        )));
    }
    let mut keyframes = Vec::with_capacity(SHAPES - 1);
    let mut prev = 0.0f32;
    for (k, off) in offsets.into_iter().enumerate() {
        let c = if k + 2 == SHAPES {
            1.0
        } else {
            (m0 - m[k + 1]) / (m0 - m1)
        };
        if !(c > prev && c <= 1.0) {
            return Err(DesignError::Geometry(format!(
                "{name}: keyframe closures not increasing ({prev} then {c}; metric {m:?})"
            )));
        }
        prev = c;
        keyframes.push(ValveKeyframe {
            closure: c,
            offsets: off,
        });
    }
    let valve = AnimatedValve {
        name: name.to_string(),
        leaflet_names: leaflet_names.iter().map(|s| (*s).to_string()).collect(),
        rest_mm: rest,
        leaflet_vertices: nl as u32,
        triangles,
        triangle_leaflet,
        vertex_leaflet,
        chordae,
        chordae_radius_mm: chord_radius_mm,
        annulus,
        free_edge,
        follow_weight,
        coaptation_mm,
        quantum_mm,
        fit_scale: 1.0,
        source_leaflet_area_mm2: Vec::new(),
        keyframes,
    };
    let mut valve = valve;
    // a designed valve has no source model: its "source" areas are its own rest areas
    valve.source_leaflet_area_mm2 = valve.leaflet_areas_mm2(&valve.rest_mm);
    // containment after quantisation, every shape
    let mut worst = (0.0f32, 0usize, 0usize);
    if let Some(mask) = blood {
        let mut pos = Vec::new();
        for k in 0..valve.keyframe_count() {
            valve.keyframe_positions(k, &mut pos);
            for (v, p) in pos[..nl].iter().enumerate() {
                let d = mask.distance_outside(*p, 12.0);
                if d > worst.0 {
                    worst = (d, k, v);
                }
            }
        }
        report.push(format!(
            "{name}: containment: opening kept per column min {kept_min:.2} / mean {kept_mean:.2} of the designed; \
             worst leaflet vertex {:.2} mm outside its blood (shape {}, vertex {})",
            worst.0, worst.1, worst.2
        ));
    }
    report.push(format!(
        "{name}: keyframe closures {}",
        valve
            .keyframes
            .iter()
            .map(|k| format!("{:.3}", k.closure))
            .collect::<Vec<_>>()
            .join(" ")
    ));
    Ok(DesignedValve {
        valve,
        report: std::mem::take(report),
        worst_outside: worst,
        opening_kept: (kept_min, kept_mean),
    })
}

fn rot(dir: Vec3, about: Vec3, deg: f32) -> Vec3 {
    glam::Quat::from_axis_angle(about, deg.to_radians()) * dir
}

/// Smallest `β ≥ 0` with `β / sin β = ratio` (`ratio ≥ 1`), by bisection on `[0, max]`.
fn arc_turn(ratio: f32, max: f32) -> f32 {
    let g = |b: f32| if b < 1e-6 { 1.0 } else { b / b.sin() };
    if ratio <= 1.0 {
        return 0.0;
    }
    if g(max) <= ratio {
        return max;
    }
    let (mut lo, mut hi) = (0.0f32, max);
    for _ in 0..40 {
        let mid = 0.5 * (lo + hi);
        if g(mid) < ratio {
            lo = mid;
        } else {
            hi = mid;
        }
    }
    0.5 * (lo + hi)
}

// --- the mitral valve -----------------------------------------------------------------------------

/// The height of the mitral leaflet at angle `a` (degrees from the anterior leaflet's centre,
/// positive toward the anterolateral side, any turn): M11 on the anterior arc, M12 on the
/// posterior one (scallops P1 anterolateral, P2, P3 posteromedial).
#[must_use]
pub fn mitral_height_mm(p: &MitralDesign, a_deg: f32) -> f32 {
    let half = 0.5 * p.anterior_arc_deg;
    let a = (a_deg + 180.0).rem_euclid(360.0) - 180.0;
    let hc = p.commissure_height_mm;
    if a.abs() <= half {
        let x = (PI * a / (2.0 * half)).cos();
        return hc + (p.anterior_length_mm - hc) * x * x;
    }
    // posterior: b from the anterolateral commissure (0) to the posteromedial one (1)
    let span = 360.0 - p.anterior_arc_deg;
    let b = (a.rem_euclid(360.0) - half) / span;
    let [f1, f2, _] = p.scallop_fractions;
    let peak = p.scallop_heights.map(|k| k * p.posterior_length_mm);
    // the indentation between two scallops: the lower neighbour's height less M9
    let dip = |l: usize, r: usize| ((1.0 - p.indentation) * peak[l].min(peak[r])).max(hc);
    let (d12, d23) = (dip(0, 1), dip(1, 2));
    // (scallop, u across it from its anterolateral end, height at that end, at the other end)
    let (k, u, left, right) = if b < f1 {
        (0, b / f1, hc, d12)
    } else if b < f1 + f2 {
        (1, (b - f1) / f2, d12, d23)
    } else {
        (2, (b - f1 - f2) / (1.0 - f1 - f2), d23, hc)
    };
    let sq = (PI * u).sin().powi(2);
    // from the end's height up to the scallop's peak at its middle and down to the other end's
    let end = if u < 0.5 { left } else { right };
    end + (peak[k] - end) * sq
}

/// Angle (degrees from the anterior leaflet's centre toward the anterolateral side) of the
/// boundary between the middle scallop and the scallop on the anterolateral side (`side = 1`) or
/// the posteromedial side (`side = −1`).
fn cleft_deg(p: &MitralDesign, side: f32) -> f32 {
    let half = 0.5 * p.anterior_arc_deg;
    let span = 360.0 - p.anterior_arc_deg;
    let [f1, f2, _] = p.scallop_fractions;
    let b = if side > 0.0 { f1 } else { f1 + f2 };
    let a = half + span * b;
    if a > 180.0 { a - 360.0 } else { a }
}

/// The designed mitral valve on `disc` (normal atrium → ventricle). `anterior` is the in-plane
/// direction of the anterior leaflet's centre (rule M-R1: toward the aortic valve);
/// `anterolateral` an in-plane direction on the anterolateral side (rule M-R2); `papillary_tips`
/// the anterolateral and posteromedial muscle tips the chordae leave from (rest frame, mm).
/// Leaflet ids: 0 anterior, 1 posterior.
///
/// # Errors
/// [`DesignError`] when the disc is degenerate or the shapes do not close monotonically.
pub fn mitral(
    disc: &DiscFrame,
    anterior: Vec3,
    anterolateral: Vec3,
    papillary_tips: [Vec3; 2],
    p: &MitralDesign,
    blood: Option<&BloodMask<'_>>,
) -> Result<DesignedValve, DesignError> {
    let n = disc.normal();
    let ua = disc
        .in_plane(anterior)
        .ok_or_else(|| DesignError::Geometry("mitral: anterior direction along the normal".into()))?;
    let mut side = n.cross(ua);
    if side.dot(anterolateral) < 0.0 {
        side = -side;
    }
    // angle a (degrees, from ua toward `side`) → in-plane direction; the rotation about n that
    // takes ua toward side
    let axis = if ua.cross(side).dot(n) >= 0.0 { n } else { -n };
    let dir = |a: f32| rot(ua, axis, a);
    let half = 0.5 * p.anterior_arc_deg;
    let span = 360.0 - p.anterior_arc_deg;
    let hinge = |a: f32| disc.rim_at_dir(dir(a));
    // t ∈ [−1, 1] along the coaptation line: t = a / half on the anterior leaflet, and the
    // posterior angle b(t) from the anterolateral commissure (t = 1) to the posteromedial (t = −1)
    let ant_a = |t: f32| half * t;
    let post_a = |t: f32| half + span * 0.5 * (1.0 - t);
    let t_of = |a: f32| -> (bool, f32) {
        let a = (a + 180.0).rem_euclid(360.0) - 180.0;
        if a.abs() <= half {
            (true, a / half)
        } else {
            (false, 1.0 - 2.0 * (a.rem_euclid(360.0) - half) / span)
        }
    };
    let mut report = Vec::new();
    let mut worst_gap_short = 0.0f32;
    let mut min_coapt = f32::INFINITY;
    let (mut max_coapt, mut centre_coapt) = (0.0f32, 0.0f32);
    let mut depths = Vec::new();
    // the meeting point of the pair at t, and the overlap used there
    let pair = |t: f32| -> (Vec3, Vec3, Vec3, f32, f32) {
        let (ha, hp) = (hinge(ant_a(t)), hinge(post_a(t)));
        let (la_full, lp_full) = (mitral_height_mm(p, ant_a(t)), mitral_height_mm(p, post_a(t)));
        let d = ha.distance(hp);
        if d < 1e-3 {
            let c = p.coaptation_mm.min(0.5 * la_full);
            return (ha + n * (la_full - c), ha, hp, c, 0.0);
        }
        let e = (hp - ha) / d;
        let np = (n - e * n.dot(e)).normalize_or(n);
        let c = p
            .coaptation_mm
            .min(0.5 * (la_full + lp_full - d) - 0.3)
            .max(p.min_coaptation_mm);
        let (la, lp) = (la_full - c, lp_full - c);
        let x = ((la * la - lp * lp + d * d) / (2.0 * d)).clamp(-1.0, d + 1.0);
        let h2 = (la * la - x * x).min(lp * lp - (d - x) * (d - x));
        let short = la + lp - d;
        (ha + e * x + np * h2.max(0.0).sqrt(), ha, hp, c, short)
    };
    let nc = p.columns;
    let step = 360.0 / nc as f32;
    let mut cols: Vec<Box<dyn Column>> = Vec::with_capacity(nc);
    let mut col_angle = Vec::with_capacity(nc);
    for j in 0..nc {
        // column 0 at the posteromedial commissure, then around through the anterior leaflet
        let a = -half + step * j as f32;
        let (is_ant, t) = t_of(a);
        let (tp, ha, hp, c, short) = pair(t);
        min_coapt = min_coapt.min(c);
        max_coapt = max_coapt.max(c);
        if t.abs() < 1e-6 {
            centre_coapt = c;
        }
        if short < 0.0 {
            worst_gap_short = worst_gap_short.max(-short);
        }
        let (h, other) = if is_ant { (ha, hp) } else { (hp, ha) };
        let len = mitral_height_mm(p, a);
        // own target: the meeting point moved back toward the own side by half the apposition
        let toward_other = disc
            .in_plane(other - h)
            .unwrap_or_else(|| disc.in_plane(disc.centre() - h).unwrap_or(ua));
        let apart = other.distance(h) > 1e-3;
        let target = if apart {
            tp - toward_other * (0.5 * p.apposition_mm)
        } else {
            tp
        };
        let rel = target - h;
        let inward = disc.in_plane(disc.centre() - h).unwrap_or(-ua);
        let proj = rel - n * rel.dot(n);
        let e = if proj.length() >= 1.0 {
            proj.normalize()
        } else {
            (proj + inward * (1.0 - proj.length())).normalize_or(inward)
        };
        let b = e.cross(n);
        let (xt, yt, wt) = (rel.dot(e), rel.dot(n).max(0.0), rel.dot(b));
        let d = Vec2::new(xt, yt).length();
        let theta_t = yt.atan2(xt);
        depths.push(yt);
        // billow toward the atrium of at most `billow_mm`, never above the hinge (θ_start ≥ 0)
        let beta0 = (4.0 * p.billow_mm / d.max(1e-3))
            .min(0.9 * theta_t)
            .min(0.6)
            .max(0.0);
        let g = |bb: f32| if bb.abs() < 1e-6 { 1.0 } else { bb / bb.sin() };
        let mut arc = d * g(beta0);
        let mut beta = beta0;
        // the free edges of a pair end level: the column whose zone would be longer than its
        // partner's puts the difference into its arc (more billow, or a belly toward the ventricle)
        let partner_zone = {
            // the partner's own straight distance and zone, as computed for it
            let other_len = mitral_height_mm(p, if is_ant { post_a(t) } else { ant_a(t) });
            let toward_me = disc.in_plane(h - other).unwrap_or(-toward_other);
            let ot = if apart {
                tp - toward_me * (0.5 * p.apposition_mm)
            } else {
                tp
            };
            let orel = ot - other;
            let od = orel.length();
            let oyt = orel.dot(n).max(0.0);
            let oproj = (orel - n * orel.dot(n)).length();
            let otheta = oyt.atan2(oproj);
            let ob = (4.0 * p.billow_mm / od.max(1e-3))
                .min(0.9 * otheta)
                .min(0.6)
                .max(0.0);
            other_len - od * g(ob)
        };
        let own_zone = len - arc;
        if own_zone > partner_zone && partner_zone > 0.0 {
            let want = len - partner_zone;
            let ratio = want / d.max(1e-3);
            let up = 0.9 * theta_t;
            let bpos = arc_turn(ratio, up.max(0.0));
            if g(bpos) >= ratio - 1e-4 {
                beta = bpos;
            } else {
                beta = -arc_turn(ratio, 1.2);
            }
            arc = d * g(beta);
        }
        if arc > len {
            arc = len;
        }
        let theta_open = FRAC_PI_2 - p.open_angle_deg.to_radians();
        cols.push(Box::new(AvColumn {
            h,
            e,
            n,
            b,
            len,
            arc,
            theta_open,
            theta_start: theta_t - beta,
            theta_end: theta_t + beta,
            w: wt,
            rows: p.rows,
        }));
        col_angle.push(a);
    }
    let half_quads: Vec<u8> = (0..nc)
        .map(|j| {
            let mid = col_angle[j] + 0.5 * step;
            u8::from(!(t_of(mid).0))
        })
        .collect();
    let strips = Strips {
        strips: vec![(0, nc, true)],
        quad_leaflet: half_quads,
    };
    // chordae: per muscle, insertions on its half (the anterolateral muscle on the positive
    // angles, the posteromedial on their mirror)
    let mut extra = Vec::new();
    let mut chords = Vec::new();
    for (m, tip) in papillary_tips.iter().enumerate() {
        let sign = if m == 0 { 1.0 } else { -1.0 };
        let rows = p.rows as f32;
        // (angle, row fraction from the annulus): the middle of the rough zone, or the free edge
        let rough = |k: usize| 1.0 - 0.5 * p.rough_zone[k];
        let spec = [
            (sign * p.chordae_anterior_deg[0], 1.0),
            (sign * p.chordae_anterior_deg[1], rough(0)),
            (sign * half, 1.0),
            (cleft_deg(p, sign), 1.0),
            (180.0 - sign * p.chordae_middle_scallop_deg[0], 1.0),
            (180.0 - sign * p.chordae_middle_scallop_deg[1], rough(1)),
        ];
        for (a, frac) in spec {
            let j = (((a + half) / step).round() as isize).rem_euclid(nc as isize) as usize;
            let row = ((frac * rows).round() as usize).min(p.rows);
            // the rest (open) position of the insertion, for the fan direction
            let mut tmp = Vec::new();
            cols[j].at(0.0, &mut tmp);
            let ins = tmp[row];
            let fan = disc.in_plane(ins - *tip).unwrap_or(ua);
            chords.push((extra.len(), j, row));
            extra.push(*tip + fan * p.chord_fan_mm);
        }
    }
    // numbers to report (on the unblended columns)
    let mut shut_col = Vec::new();
    cols[(half / step).round() as usize % nc].at(1.0, &mut shut_col);
    let mid_ant_len: f32 = shut_col.windows(2).map(|w| w[0].distance(w[1])).sum();
    let post_mid = ((half + 0.5 * span + half) / step).round() as usize % nc;
    cols[post_mid].at(1.0, &mut shut_col);
    let mid_post_len: f32 = shut_col.windows(2).map(|w| w[0].distance(w[1])).sum();
    report.push(format!(
        "mitral: anterior leaflet length {mid_ant_len:.2} mm (designed {}), posterior (P2) {mid_post_len:.2} mm \
         (designed {}); overlap used {min_coapt:.2}–{max_coapt:.2} mm, {centre_coapt:.2} mm at the leaflets' centres (designed {}); columns too short to meet by up to \
         {worst_gap_short:.2} mm; coaptation depth below the annulus {:.1}–{:.1} mm",
        p.anterior_length_mm,
        p.posterior_length_mm,
        p.coaptation_mm,
        depths.iter().copied().fold(f32::INFINITY, f32::min),
        depths.iter().copied().fold(0.0f32, f32::max),
    ));
    let mut out = assemble(
        "mitral",
        &["anterior", "posterior"],
        &cols,
        p.rows,
        &strips,
        &extra,
        &chords,
        p.chord_radius_mm,
        blood,
        &mut report,
    )?;
    let areas = out.valve.leaflet_areas_mm2(&{
        let mut s = Vec::new();
        out.valve
            .keyframe_positions(out.valve.keyframe_count() - 1, &mut s);
        s
    });
    out.report.push(format!(
        "mitral: shut leaflet areas anterior {:.0} mm², posterior {:.0} mm², total / annulus area {:.2} \
         (annulus {:.0} mm²; M16: about 2, secondary)",
        areas[0],
        areas[1],
        (areas[0] + areas[1]) / disc.area_mm2().max(1.0),
        disc.area_mm2()
    ));
    Ok(out)
}

// --- the semilunar valves -------------------------------------------------------------------------

/// A designed semilunar valve (`name` `"aortic"` or `"pulmonary"`) on `disc` (normal ventricle →
/// artery). Cusp `k` is centred at `first_cusp` turned by `120° · k` about the normal (the
/// right-hand turn about it), named `cusp_names[k]`. With `blood`: each attachment point that lies
/// outside it is moved toward the axis until it is inside (the vessels are tubes without sinuses);
/// when the shut cusps still leave it (a vessel that ends short of the commissures), every height is
/// scaled down in steps of 5 % (to at most 0.3) until they fit; and each column's opening is
/// shortened until the open cusp fits. The report says how much of each was needed.
///
/// # Errors
/// [`DesignError`] when the disc is degenerate or the shapes do not close monotonically.
#[allow(clippy::too_many_lines)]
pub fn semilunar(
    name: &str,
    cusp_names: [&str; 3],
    disc: &DiscFrame,
    first_cusp: Vec3,
    p: &CuspDesign,
    blood: Option<&BloodMask<'_>>,
) -> Result<DesignedValve, DesignError> {
    let n = disc.normal();
    let w0 = disc
        .in_plane(first_cusp)
        .ok_or_else(|| DesignError::Geometry(format!("{name}: cusp direction along the normal")))?;
    let centre = disc.centre();
    let r_mean = disc.mean_radius_mm();
    let dir = |deg: f32| rot(w0, n, deg);
    let half_gap = 0.5 * p.apposition_mm;
    let delta = half_gap / (PI / 3.0).sin();
    let nc = p.columns;
    let lim = 60.0 - p.commissure_gap_deg;
    let phis: Vec<f32> = (0..nc)
        .map(|j| -lim + 2.0 * lim * j as f32 / (nc - 1) as f32)
        .collect();
    // open free edge: radius fraction at the cusp centre, so the open orifice is the designed share
    // of the disc (on the rim's own radii)
    let open_rho = |phi: f32, k_mid: f32| 1.0 - (1.0 - k_mid) * (1.5 * phi.to_radians()).cos().powi(2);
    let orifice = |k_mid: f32| -> f32 {
        let mut pts = Vec::new();
        for k in 0..3 {
            for &phi in &phis {
                let az = 120.0 * k as f32 + phi;
                let r = disc.to2(disc.rim_at_dir(dir(az))).length();
                let d = dir(az);
                pts.push(disc.to2(centre + d * r * open_rho(phi, k_mid)));
            }
        }
        polygon_area(&pts) / disc.area_mm2().max(1e-6)
    };
    let (mut lo, mut hi) = (0.0f32, 1.0f32);
    for _ in 0..40 {
        let mid = 0.5 * (lo + hi);
        if orifice(mid) < p.open_orifice_fraction {
            lo = mid;
        } else {
            hi = mid;
        }
    }
    let k_mid = hi;
    // the cusps with every height (effective, commissure, apposed zone) times `hs`
    struct Built {
        cols: Vec<Box<dyn Column>>,
        quad_leaflet: Vec<u8>,
        strips: Vec<(usize, usize, bool)>,
        pulled_max: f32,
        free_edge_shut: f32,
        shut_worst: f32,
        shut_worst_at: (f32, f32, f32),
        eh: f32,
        hc: f32,
    }
    // the designed heights before any fit: a geometric-height ratio (pulmonary, Lis 2023) or the
    // effective height (aortic), tied by A4
    let (eh0, gh0) = match p.geometric_height_ratio {
        Some(k) => {
            let gh = k * 2.0 * r_mean;
            ((gh * gh - r_mean * r_mean).max(1.0).sqrt(), gh)
        }
        None => (
            p.effective_height_mm,
            (r_mean * r_mean + p.effective_height_mm * p.effective_height_mm).sqrt(),
        ),
    };
    let build = |hs: f32| -> Built {
        let eh = eh0 * hs;
        let gh = gh0;
        let hc = p.commissure_ratio * gh * hs;
        let crown = |phi_deg: f32| hc * (1.0 - (3.0 * phi_deg.to_radians()).cos()) * 0.5;
        let mut pulled_max = 0.0f32;
        // the attachment point at azimuth `az` (degrees from w0) and local angle `phi`
        let mut attach = |az: f32, phi: f32| -> Vec3 {
            let base = disc.rim_at_dir(dir(az)) + n * crown(phi);
            let Some(mask) = blood else { return base };
            let axis_pt = centre + n * crown(phi);
            let mut q = base;
            let mut moved = 0.0f32;
            while mask.distance_outside(q, 4.0) > 0.0 && moved < 8.0 {
                moved += 0.25;
                q = base + (axis_pt - base).normalize_or_zero() * moved;
            }
            pulled_max = pulled_max.max(moved);
            q
        };
        let z_centre = centre + n * eh;
        let mut cols: Vec<Box<dyn Column>> = Vec::with_capacity(3 * nc);
        let mut quad_leaflet = Vec::with_capacity(3 * nc);
        let mut strips = Vec::new();
        let mut free_edge_shut = 0.0f32;
        let mut shut_worst = 0.0f32;
        let mut shut_worst_at = (0.0f32, 0.0f32, 0.0f32);
        for k in 0..3 {
            let psi = 120.0 * k as f32;
            let wk = dir(psi);
            let c_plus = attach(psi + 60.0, 60.0) + dir(psi - 30.0) * half_gap;
            let c_minus = attach(psi - 60.0, -60.0) + dir(psi + 30.0) * half_gap;
            let zk = z_centre + wk * delta;
            strips.push((cols.len(), nc, false));
            let mut prev_f: Option<Vec3> = None;
            for &phi in &phis {
                let a = attach(psi + phi, phi);
                let f = phi.abs() / 60.0;
                let cside = if phi >= 0.0 { c_plus } else { c_minus };
                let free = zk + (cside - zk) * f;
                let band = p.coaptation_mm
                    + (p.lateral_coaptation_mm - p.coaptation_mm) * (PI * phi.abs() / 60.0).sin();
                let z = band * hs * ((60.0 - phi.abs()) / p.zone_taper_deg).clamp(0.0, 1.0);
                let low = free - n * z;
                let shut = resample(&[a, low, free], p.rows);
                if let Some(mask) = blood {
                    for q in &shut {
                        let d = mask.distance_outside(*q, 4.0);
                        if d > shut_worst {
                            shut_worst = d;
                            shut_worst_at = (psi + phi, (*q - centre).dot(n), disc.to2(*q).length());
                        }
                    }
                }
                let col_len = a.distance(low) + z;
                if let Some(pf) = prev_f {
                    free_edge_shut += pf.distance(free);
                }
                prev_f = Some(free);
                // open: the free edge toward the wall at this azimuth, as high as the column's
                // length lets it (never above the commissures)
                let r_here = disc.to2(a).length();
                let fo2 = dir(psi + phi) * (r_here * open_rho(phi, k_mid));
                let to_free = centre + fo2 - a;
                let hd = (to_free - n * to_free.dot(n)).length();
                let h_a = (a - centre).dot(n);
                let h_open = (h_a + (col_len * col_len - hd * hd).max(0.0).sqrt()).min(hc);
                let fo = centre + fo2 + n * h_open;
                let open = resample(&[a, fo], p.rows);
                cols.push(Box::new(LerpColumn { shut, open }));
                quad_leaflet.push(k as u8);
            }
        }
        Built {
            cols,
            quad_leaflet,
            strips,
            pulled_max,
            free_edge_shut,
            shut_worst,
            shut_worst_at,
            eh,
            hc,
        }
    };
    // the largest height scale (1, 0.95, … 0.3) whose shut cusps stay in the blood: a vessel that
    // ends short of the commissures (a stub in the label volume) gets a lower valve, not an edit
    let mut hs = 1.0f32;
    let mut b = build(hs);
    let mut tried = Vec::new();
    while blood.is_some() && b.shut_worst > CONTAIN_TARGET_MM && hs > 0.31 {
        tried.push(format!(
            "{hs:.2}: {:.1} mm out at azimuth {:.0}°, height {:.1} mm, radius {:.1} mm",
            b.shut_worst, b.shut_worst_at.0, b.shut_worst_at.1, b.shut_worst_at.2
        ));
        hs -= 0.05;
        b = build(hs);
    }
    let Built {
        cols,
        quad_leaflet,
        strips,
        pulled_max,
        free_edge_shut,
        eh,
        hc,
        ..
    } = b;
    // the centre column's straight and along-surface lengths (φ = 0)
    let centre_col = phis
        .iter()
        .enumerate()
        .min_by(|a, b| a.1.abs().total_cmp(&b.1.abs()))
        .map_or(0, |x| x.0);
    let mut s = Vec::new();
    cols[centre_col].at(1.0, &mut s);
    let straight = s[0].distance(s[p.rows]);
    let along: f32 = s.windows(2).map(|w| w[0].distance(w[1])).sum();
    let eff = (s[p.rows] - centre).dot(n);
    let gh = (r_mean * r_mean + eh * eh).sqrt();
    let mut report = vec![format!(
        "{name}: disc mean radius {r_mean:.2} mm; heights at {hs:.2} of the designed (effective {eh:.2} mm, \
         commissure {hc:.2} mm; √(R² + eH²) {gh:.2} mm); centre column: effective height {eff:.2} mm, nadir → \
         free-edge midpoint {straight:.2} mm straight, {along:.2} mm along the cusp (with the {:.1} mm apposed \
         zone); shut free edge {:.1} mm per cusp (bracket 24.5–34.3 mm); open orifice designed {:.2} of the disc \
         (centre radius fraction {k_mid:.3}); attachment moved toward the axis by up to {pulled_max:.2} mm to stay \
         in the blood; height scales refused: [{}]",
        p.coaptation_mm * hs,
        free_edge_shut / 3.0,
        p.open_orifice_fraction,
        tried.join("; "),
    )];
    let st = Strips { strips, quad_leaflet };
    let out = assemble(
        name,
        &cusp_names,
        &cols,
        p.rows,
        &st,
        &[],
        &[],
        0.0,
        blood,
        &mut report,
    )?;
    Ok(out)
}

/// Measures of a designed (or any) [`AnimatedValve`] that the acceptance tests of brief B36 use,
/// here so the generator's own tests and the pack's tests measure alike.
pub mod checks {
    use super::{DiscFrame, polygon_area};
    use crate::mesh::closest_point_on_triangle;
    use crate::valve::AnimatedValve;
    use glam::Vec3;
    use std::collections::{HashMap, HashSet};

    fn segment_distance(p: Vec3, a: Vec3, b: Vec3) -> f32 {
        let ab = b - a;
        let t = ((p - a).dot(ab) / ab.length_squared().max(1e-12)).clamp(0.0, 1.0);
        (a + ab * t).distance(p)
    }

    /// The free edge as segments of one leaflet each: consecutive free-edge vertices (record order,
    /// wrapping) that belong to the same leaflet.
    fn free_segments(v: &AnimatedValve) -> Vec<(u8, u32, u32)> {
        let f = &v.free_edge;
        (0..f.len())
            .filter_map(|i| {
                let (a, b) = (f[i], f[(i + 1) % f.len()]);
                let (la, lb) = (v.vertex_leaflet[a as usize], v.vertex_leaflet[b as usize]);
                (la == lb).then_some((la, a, b))
            })
            .collect()
    }

    /// Largest gap between the free edges of `pos` (a shut shape): for each free-edge vertex the
    /// distance to the nearest free-edge segment of another leaflet, the largest over the vertices,
    /// mm, with the vertex.
    #[must_use]
    pub fn free_edge_gap_mm(v: &AnimatedValve, pos: &[Vec3]) -> (f32, u32) {
        let segs = free_segments(v);
        let mut worst = (0.0f32, 0u32);
        for &i in &v.free_edge {
            let l = v.vertex_leaflet[i as usize];
            let d = segs
                .iter()
                .filter(|s| s.0 != l)
                .map(|s| segment_distance(pos[i as usize], pos[s.1 as usize], pos[s.2 as usize]))
                .fold(f32::INFINITY, f32::min);
            if d.is_finite() && d > worst.0 {
                worst = (d, i);
            }
        }
        worst
    }

    /// Area of the orifice the free edge of `pos` leaves, over the disc's area: the free-edge
    /// vertices projected on the disc plane, ordered by azimuth about the centre (a star-shaped
    /// opening), as a polygon.
    #[must_use]
    pub fn orifice_fraction(v: &AnimatedValve, pos: &[Vec3], disc: &DiscFrame) -> f32 {
        let mut pts: Vec<glam::Vec2> = v.free_edge.iter().map(|&i| disc.to2(pos[i as usize])).collect();
        pts.sort_by(|a, b| a.y.atan2(a.x).total_cmp(&b.y.atan2(b.x)));
        polygon_area(&pts) / disc.area_mm2().max(1e-6)
    }

    /// The largest share of any leaflet vertex's whole open-to-shut path (summed over the keyframe
    /// segments) that one keyframe segment takes, over the vertices that move at least 0.1 mm, with
    /// the vertex. The brief's no-snap rule asks for at most 0.25.
    #[must_use]
    pub fn largest_step_share(v: &AnimatedValve) -> (f32, usize) {
        let nl = v.leaflet_vertices as usize;
        let shapes: Vec<Vec<Vec3>> = (0..v.keyframe_count())
            .map(|k| {
                let mut p = Vec::new();
                v.keyframe_positions(k, &mut p);
                p
            })
            .collect();
        let mut worst = (0.0f32, 0usize);
        for i in 0..nl {
            let steps: Vec<f32> = shapes.windows(2).map(|w| w[0][i].distance(w[1][i])).collect();
            let total: f32 = steps.iter().sum();
            if total < 0.1 {
                continue;
            }
            let share = steps.iter().copied().fold(0.0f32, f32::max) / total;
            if share > worst.0 {
                worst = (share, i);
            }
        }
        worst
    }

    fn excursion(t: [Vec3; 3], u: [Vec3; 3]) -> f32 {
        let n = (u[1] - u[0]).cross(u[2] - u[0]).normalize_or_zero();
        let d = t.map(|p| (p - u[0]).dot(n));
        let up = d.iter().copied().fold(0.0f32, f32::max);
        let down = -d.iter().copied().fold(0.0f32, f32::min);
        up.min(down)
    }

    fn segment_hits_triangle(p: Vec3, q: Vec3, t: [Vec3; 3]) -> bool {
        let (e1, e2) = (t[1] - t[0], t[2] - t[0]);
        let dir = q - p;
        let h = dir.cross(e2);
        let a = e1.dot(h);
        if a.abs() < 1e-9 {
            return false;
        }
        let f = 1.0 / a;
        let s = p - t[0];
        let u = f * s.dot(h);
        if !(0.0..=1.0).contains(&u) {
            return false;
        }
        let qv = s.cross(e1);
        let w = f * dir.dot(qv);
        if w < 0.0 || u + w > 1.0 {
            return false;
        }
        let tt = f * e2.dot(qv);
        (0.0..=1.0).contains(&tt)
    }

    /// The deepest crossing of one leaflet through another in `pos`, mm: over the intersecting
    /// pairs of triangles of different leaflets that share no vertex, the smaller excursion of
    /// either through the other's plane (the rule of the B35 test).
    #[must_use]
    pub fn deepest_crossing_mm(v: &AnimatedValve, pos: &[Vec3]) -> f32 {
        let cell = 3.0f32;
        let mut grid: HashMap<[i32; 3], Vec<usize>> = HashMap::new();
        for (ti, t) in v.triangles.iter().enumerate() {
            let [a, b, c] = t.map(|i| pos[i as usize]);
            let (lo, hi) = (a.min(b).min(c) / cell, a.max(b).max(c) / cell);
            for z in lo.z.floor() as i32..=hi.z.floor() as i32 {
                for y in lo.y.floor() as i32..=hi.y.floor() as i32 {
                    for x in lo.x.floor() as i32..=hi.x.floor() as i32 {
                        grid.entry([x, y, z]).or_default().push(ti);
                    }
                }
            }
        }
        let mut worst = 0.0f32;
        let mut checked = HashSet::new();
        for list in grid.values() {
            for (i, &ta) in list.iter().enumerate() {
                for &tb in &list[i + 1..] {
                    if v.triangle_leaflet[ta] == v.triangle_leaflet[tb] {
                        continue;
                    }
                    let (a, b) = (v.triangles[ta], v.triangles[tb]);
                    if a.iter().any(|x| b.contains(x)) || !checked.insert((ta.min(tb), ta.max(tb))) {
                        continue;
                    }
                    let pa = a.map(|i| pos[i as usize]);
                    let pb = b.map(|i| pos[i as usize]);
                    let hit = (0..3).any(|e| segment_hits_triangle(pa[e], pa[(e + 1) % 3], pb))
                        || (0..3).any(|e| segment_hits_triangle(pb[e], pb[(e + 1) % 3], pa));
                    if hit {
                        worst = worst.max(excursion(pa, pb).min(excursion(pb, pa)));
                    }
                }
            }
        }
        worst
    }

    /// Over `steps + 1` openings from shut to open, the largest fall of the closure metric
    /// ([`AnimatedValve::closure_metric_mm`]) from one opening to the next larger one, mm: `0` when
    /// the free edge comes monotonically nearer the coaptation point as the valve shuts; with the
    /// opening where it happens.
    #[must_use]
    pub fn closure_metric_largest_fall(v: &AnimatedValve, steps: usize) -> (f32, f32) {
        let mut pos = Vec::new();
        let mut prev = f32::NEG_INFINITY;
        let mut worst = (0.0f32, 0.0f32);
        for k in 0..=steps {
            let o = k as f32 / steps as f32;
            v.pose_rest(o, &mut pos);
            let m = v.closure_metric_mm(&pos);
            if prev - m > worst.0 {
                worst = (prev - m, o);
            }
            prev = m;
        }
        worst
    }

    /// Whether point `x` lies within `half_mm` of a leaflet triangle of `pos` (brute force: the
    /// reference the echo's gridded test is checked against).
    #[must_use]
    pub fn within_of_leaflets(v: &AnimatedValve, pos: &[Vec3], x: Vec3, half_mm: f32) -> bool {
        v.triangles.iter().any(|t| {
            let [a, b, c] = t.map(|i| pos[i as usize]);
            closest_point_on_triangle(x, a, b, c).distance_squared(x) <= half_mm * half_mm
        })
    }
}
